const order = $input.first().json.body.order;
const taxRate = order.taxRate ?? 20;

let subtotal = 0;
const items = order.lines.map((l) => {
  const quantity = Number(l.quantity);
  const unitPrice = Number(l.unitPrice);
  const lineTotal = Math.round(quantity * unitPrice * 100) / 100;
  subtotal += lineTotal;
  return {
    name: l.name,
    description: l.description ?? '',
    quantity,
    unit_price: unitPrice,
    line_total: lineTotal,
  };
});

subtotal = Math.round(subtotal * 100) / 100;
const taxAmount = Math.round(subtotal * taxRate) / 100;
const total = Math.round((subtotal + taxAmount) * 100) / 100;

const issueDate = order.issueDate ?? new Date().toISOString().slice(0, 10);
const invoiceNumber = order.invoiceNumber ?? `INV-${issueDate.slice(0, 7)}-${order.orderId}`;
const currency = order.currencyCode ?? 'EUR';
const money = (n) => `${currency} ${n.toFixed(2)}`;

const invoice = {
  invoice_number: invoiceNumber,
  invoice_date: issueDate,
  due_date: order.dueDate ?? '',
  currency,
  customer_name: order.customer.name,
  customer_email: order.customer.email,
  items,
  subtotal,
  subtotal_formatted: money(subtotal),
  tax_rate: taxRate,
  tax_amount: taxAmount,
  tax_formatted: money(taxAmount),
  total,
  total_formatted: money(total),
};

return [{ json: invoice }];
